package api

import("github.com/softrenzu/Prometheus/internal/engine";"net/http";"strconv";"time")
func parseTimeParam(v string,def int64)int64{if v==""{return def};if f,err:=strconv.ParseFloat(v,64);err==nil{return int64(f*1000)};if t,err:=time.Parse(time.RFC3339,v);err==nil{return t.UnixMilli()};return def}
func(s *Server)query(w http.ResponseWriter,r *http.Request){expr:=r.URL.Query().Get("query");q,err:=engine.ParseQuery(expr);if err!=nil{promError(w,400,err);return};at:=parseTimeParam(r.URL.Query().Get("time"),time.Now().UnixMilli());series:=s.Store.Select(tenant(r),q.Metric,q.Matchers,0,at);if q.Func=="rate"{for i:=range series{series[i]=engine.Rate(series[i])}};series=engine.AggregateInstant(q.Func,series);if r.Header.Get("X-Rooom-Internal")==""{series=append(series,s.queryPeers(r.Context(),tenant(r),expr,0,at,0)...);if q.Func!=""&&q.Func!="rate"{series=engine.AggregateInstant(q.Func,series)}};jsonResponse(w,200,map[string]any{"status":"success","data":map[string]any{"resultType":"vector","result":instantData(series)}})}
func(s *Server)queryRange(w http.ResponseWriter,r *http.Request){expr:=r.URL.Query().Get("query");q,err:=engine.ParseQuery(expr);if err!=nil{promError(w,400,err);return};start:=parseTimeParam(r.URL.Query().Get("start"),time.Now().Add(-time.Hour).UnixMilli());end:=parseTimeParam(r.URL.Query().Get("end"),time.Now().UnixMilli());step:=engine.ParseStep(r.URL.Query().Get("step"));series:=s.Store.Select(tenant(r),q.Metric,q.Matchers,start,end);if q.Func=="rate"{for i:=range series{series[i]=engine.Rate(series[i])}};for i:=range series{series[i].Points=engine.Downsample(series[i].Points,step,11000)};if r.Header.Get("X-Rooom-Internal")==""{series=append(series,s.queryPeers(r.Context(),tenant(r),expr,start,end,step)...)};jsonResponse(w,200,map[string]any{"status":"success","data":map[string]any{"resultType":"matrix","result":matrixData(series)}})}
func(s *Server)internalQuery(w http.ResponseWriter,r *http.Request){r.Header.Set("X-Rooom-Internal","1");if r.URL.Query().Get("range")=="1"{s.queryRange(w,r)}else{s.query(w,r)}}
